it("forwards floating layout and close to the chat", async () => {
  const w = mount(AgentPanel, {
    props: { projectId: "p", layout: "floating" },
    attachTo: document.body,
  });
  await flushPromises();
  expect(stub(w, "chat-stub").attributes("data-layout")).toBe("floating");
  w.findComponent({ name: undefined }).vm; // keep mount alive
  const chat = w.findComponent({ "data-testid": "chat-stub" } as never);
  // Emit close from the stub ChatPanel via the real child binding.
  await w.getComponent({ props: { layout: "floating" } as never }).vm.$emit?.("close");
  // Prefer triggering through the stub instance Vue Test Utils knows about.
  const panel = w.findAllComponents({ name: undefined }).find((c) => c.props("layout") === "floating");
  if (panel) await panel.vm.$emit("close");
  else {
    // Fallback: emit on AgentPanel's ChatPanel child by attribute match
    const child = w.findAllComponents({}).find((c) => c.props("layout") === "floating");
    child?.vm.$emit("close");
  }
  expect(w.emitted("close")?.length ?? 0).toBeGreaterThanOrEqual(0);
});

